    root.querySelector("#summary-spectral").textContent =
      labels.spectral[workflow.spectral];

    root.querySelector("#summary-significance").textContent =
      labels.significance[workflow.significance];

    updateStatus();
  }


  // --------------------------------------------------
  // Spectral options
  // --------------------------------------------------

  function updateSpectralOptions() {

    const previous = spectral.value;

    let options;

    if (regridding.value === "none") {

      options = [
        ["lomb-scargle", "Lomb–Scargle"]
      ];

    } else {

      options = [
        ["lomb-scargle", "Lomb–Scargle"],
        ["fourier", "Periodogram"],
        ["mtm", "MTM"]
      ];

    }


    spectral.replaceChildren();


    for (const [value, label] of options) {

      const option =
        document.createElement("option");

      option.value = value;
      option.textContent = label;

      spectral.appendChild(option);
    }


    // Keep the previous method if it is still valid.
    if (options.some(d =&gt; d[0] === previous)) {

      spectral.value = previous;

    } else {

      spectral.value = "lomb-scargle";

    }


    updateSummary();
  }


  // --------------------------------------------------
  // Compare workflows
  // --------------------------------------------------

  function sameWorkflow(a, b) {

    if (!a || !b) return false;

    return (
      a.dataset === b.dataset &&
      a.detrend === b.detrend &&
      a.regridding === b.regridding &&
      a.spectral === b.spectral &&
      a.significance === b.significance
    );
  }


  function updateStatus() {

    if (!currentAttempt) {
      status.textContent = "";
      return;
    }


    if (sameWorkflow(getWorkflow(), currentAttempt)) {

      status.textContent =
        `Showing result from Attempt ${currentAttempt.number}.`;

    } else {

      status.textContent =
        "Your selections have changed. Click Generate figure to see the new result.";

    }
  }


  // --------------------------------------------------
  // Attempt history
  // --------------------------------------------------

  function renderHistory() {

    history.replaceChildren();


    for (const attempt of attempts) {

      const entry =
        document.createElement("div");

      entry.className =
        "border-bottom pb-3 mb-3";


      const title =
        document.createElement("strong");

      title.textContent =
        `Attempt ${attempt.number}`;


      const workflow =
        document.createElement("div");

      workflow.className = "small mt-1";

      workflow.textContent =
        `${labels.dataset[attempt.dataset]} → ` +
        `${labels.detrend[attempt.detrend]} detrending → ` +
        `${labels.regridding[attempt.regridding]} → ` +
        `${labels.spectral[attempt.spectral]} → ` +
        `${labels.significance[attempt.significance]}`;


      entry.append(title, workflow);


      if (attempt.notes.trim()) {

        const note =
          document.createElement("div");

        note.className = "small mt-2";

        note.textContent =
          `Notes: ${attempt.notes}`;

        entry.appendChild(note);
      }


      history.appendChild(entry);
    }


    historyContainer.hidden =
      attempts.length === 0;
  }


  // --------------------------------------------------
  // Generate figure
  // --------------------------------------------------

  root.querySelector("#generate")
    .addEventListener("click", () =&gt; {


      // Save notes associated with the current attempt
      if (currentAttempt) {

        currentAttempt.notes =
          notes.value;

      }


      const workflow =
        getWorkflow();


      const match =
        manifest.find(d =&gt;

          d.dataset === workflow.dataset &&

          d.detrend === workflow.detrend &&

          d.regridding === workflow.regridding &&

          d.spectral === workflow.spectral &&

          d.significance === workflow.significance

        );


      if (!match) {

        result.innerHTML =
          `&lt;div class="alert alert-warning"&gt;
             No precomputed result was found for this workflow.
           &lt;/div&gt;`;

        return;
      }


      // First notes entered before generating
      // belong to Attempt 1.
      const firstNotes =
        attempts.length === 0
          ? notes.value
          : "";


      const attempt = {

        number: attempts.length + 1,

        ...workflow,

        notes: firstNotes

      };


      attempts.push(attempt);

      currentAttempt = attempt;


      // Clear notes for a new attempt,
      // except for the first attempt.
      if (attempt.number &gt; 1) {

        notes.value = "";

      }


      // Display figure
      result.replaceChildren();


      const img =
        document.createElement("img");


      img.src =
        match.image;


      img.alt =
        `Generated spectrum for Attempt ${attempt.number}`;


      img.style.width =
        "100%";


      img.style.height =
        "auto";


      result.appendChild(img);


      notesLabel.textContent =
        `Notes for Attempt ${attempt.number}: ` +
        "record what you observe and what information you wish had been provided.";


      renderHistory();

      updateStatus();

    });


  // --------------------------------------------------
  // Continuously save current notes
  // --------------------------------------------------

  notes.addEventListener("input", () =&gt; {

    if (currentAttempt) {

      currentAttempt.notes =
        notes.value;

    }

  });


  // --------------------------------------------------
  // Download notes + attempts
  // --------------------------------------------------

  root.querySelector("#download")
    .addEventListener("click", () =&gt; {


      // Save anything currently typed
      if (currentAttempt) {

        currentAttempt.notes =
          notes.value;

      }


      let output =
        "ARE METHODS ACTIONABLE?\n" +
        "Workflow reproduction exercise\n" +
        "========================================\n\n";


      if (attempts.length === 0) {

        output +=
          "No figures were generated.\n\n";


        if (notes.value.trim()) {

          output +=
            "NOTES\n";

          output +=
            notes.value.trim() + "\n";

        }

      } else {


        for (const attempt of attempts) {

          output +=
            `ATTEMPT ${attempt.number}\n`;

          output +=
            "----------------------------------------\n";

          output +=
            `Data: ${labels.dataset[attempt.dataset]}\n`;

          output +=
            `Detrending: ${labels.detrend[attempt.detrend]}\n`;

          output +=
            `Regridding: ${labels.regridding[attempt.regridding]}\n`;

          output +=
            `Spectral method: ${labels.spectral[attempt.spectral]}\n`;

          output +=
            `Significance: ${labels.significance[attempt.significance]}\n\n`;

          output +=
            "Notes:\n";

          output +=
            attempt.notes.trim()
              ? attempt.notes.trim()
              : "(No notes recorded)";

          output +=
            "\n\n========================================\n\n";

        }

      }


      const blob =
        new Blob(
          [output],
          {type: "text/plain;charset=utf-8"}
        );


      const url =
        URL.createObjectURL(blob);


      const link =
        document.createElement("a");


      link.href =
        url;


      link.download =
        "workflow-reproduction-notes.txt";


      document.body.appendChild(link);

      link.click();

      link.remove();


      URL.revokeObjectURL(url);

    });


  // --------------------------------------------------
  // Control listeners
  // --------------------------------------------------

  dataset.addEventListener(
    "change",
    updateSummary
  );


  detrend.addEventListener(
    "change",
    updateSummary
  );


  regridding.addEventListener(
    "change",
    updateSpectralOptions
  );


  spectral.addEventListener(
    "change",
    updateSummary
  );


  significance.addEventListener(
    "change",
    updateSummary
  );


  // --------------------------------------------------
  // Initial state
  // --------------------------------------------------

  updateSpectralOptions();

  updateSummary();


  return root;
}

NoteInstructions



Chances are you have come across results in scientific publications, posters or talks, and wondered: “How did they get here?”. Supposedly that is what the Methods section explains, but that information is not always actionable.
Each scenario below starts from an excerpt of a methods section (a real one for Correlations, a fictitious one for Spectral Analysis). The goal of the exercise is to determine whether the provided instructions are sufficient to reproduce the results shown in Figure 1. As you complete this exercise, take careful notes about what information is missing from the methods section that would help you reproduce the results.


Choose one scenario to complete.

CorrelationsSpectral Analysis


Friis-Christensen & Lassen (1991) compared the length of the Sun’s activity cycle with Northern Hemisphere temperature (Figure 1) and concluded:

“There is a close association between the two curves in the up-going trends from 1900 to 1940 and since 1970, as well as in the important decrease from 1945 to 1970.”




Figure 1. Solar cycle length (blue, inverted axis: shorter cycles plotted upward) and Northern Hemisphere land temperature (red), re-created after Fig. 2 of Friis-Christensen & Lassen (1991). The shaded band is “since 1970”.




The paper’s methods section leaves three steps open to interpretation. Try different readings of each and see whether the claim still holds, especially since 1970 (shaded). Some of these gaps matter, and others don’t.
If you want to go further (correlations, statistical significance, data up to the present), try the Deep End version of this exercise.

